package com.hireflow.api.interview; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class Interview { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long applicationId; String candidateEmail; LocalDateTime scheduledAt; String type; String meetingLink; String status="SCHEDULED"; public Interview(){} public Long getId(){return id;} public Long getApplicationId(){return applicationId;} public String getCandidateEmail(){return candidateEmail;} public LocalDateTime getScheduledAt(){return scheduledAt;} public String getType(){return type;} public String getMeetingLink(){return meetingLink;} public String getStatus(){return status;} public void setApplicationId(Long v){applicationId=v;} public void setCandidateEmail(String v){candidateEmail=v;} public void setScheduledAt(LocalDateTime v){scheduledAt=v;} public void setType(String v){type=v;} public void setMeetingLink(String v){meetingLink=v;} }